const findClient = (clientName) => {
  if (!clientName) return null;
  const normalize = (str) => str.toLowerCase().replace(/[^a-z0-9]/g, "");
  const searchStr = normalize(clientName);
  let fallbackMatch = null;
  for (const client of CLIENT_LOGOS_ARRAY) {
    const clientStr = normalize(client.name);
    if (clientStr === searchStr) {
      return client;
    }
    if (clientStr.includes(searchStr) || searchStr.includes(clientStr)) {
      fallbackMatch = client;
    }
  }
  return fallbackMatch;
};
export {
  AGENTIC_USECASES,
  CAROUSEL_IMAGES,
  CAROUSEL_IMAGES_TEXT,
  findClient
};
